        private void HandleFilters(HttpContext context)
        {
            string strListType = GetRequestValue(context, "listType");
            string strScienceId = GetRequestValue(context, "scienceId");
            string strCourseId = GetRequestValue(context, "courseId");

            if (strListType == null || strListType == "")
            {
                WriteJson(context, false, "Thiếu loại danh sách lọc.", null);
                return;
            }

            byte byListType = Convert.ToByte(strListType);
            SIM_Class objClass = new SIM_Class();
            DataTable dtbItems = objClass.GetDataTable(
                SP_FILTER,
                "@ScienceID", NormalizeFilter(strScienceId),
                "@CourseID", NormalizeFilter(strCourseId),
                "@ListType", byListType);

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["items"] = DataTableToList(dtbItems);

            WriteJson(context, true, "", dicData);
        }

        private void HandleData(HttpContext context)
        {
            string strYearId = GetRequestValue(context, "yearId");
            string strSemester = GetRequestValue(context, "semester");
            string strScienceId = GetRequestValue(context, "scienceId");
            string strCourseId = GetRequestValue(context, "courseId");
            string strClassId = GetRequestValue(context, "classId");

            if (strYearId == null || strYearId.Trim() == "" || strYearId == "0")
            {
                WriteJson(context, false, "Vui lòng chọn Năm học.", null);
                return;
            }

            if (strSemester == null || strSemester.Trim() == "" || strSemester == "-1" || strSemester == "0")
            {
                WriteJson(context, false, "Vui lòng chọn Học kỳ.", null);
                return;
            }

            int intYearId = Convert.ToInt32(strYearId);
            byte bySemester = Convert.ToByte(strSemester);

            DataTable dtbRaw = LoadGraduationData(
                intYearId,
                bySemester,
                strScienceId,
                strCourseId,
                strClassId);

            if (dtbRaw == null)
            {
                WriteJson(context, false, "Không tải được dữ liệu từ hệ thống.", null);
                return;
            }

            Dictionary<string, object> dicAggregated = BuildAggregatedData(dtbRaw);

            Dictionary<string, object> dicData = new Dictionary<string, object>();
            dicData["summary"] = dicAggregated["summary"];
            dicData["eligibleStatus"] = dicAggregated["eligibleStatus"];
            dicData["byClass"] = dicAggregated["byClass"];
            dicData["byCourse"] = dicAggregated["byCourse"];
            dicData["byScience"] = dicAggregated["byScience"];
            dicData["graduationLevel"] = dicAggregated["graduationLevel"];
            dicData["updatedAt"] = DateTime.Now.ToString("dd/MM/yyyy HH:mm");

            WriteJson(context, true, "", dicData);
        }

        private DataTable LoadGraduationData(
            int yearId,
            byte semester,
            string scienceId,
            string courseId,
            string classId)
        {
            SIM_GraduationResult obj = new SIM_GraduationResult();
            return obj.GetDataTable(
                SP_DATA,
                "@ScienceIDList", BuildIdListParam(scienceId),
                "@CourseIDList", BuildIdListParam(courseId),
                "@TrainingLevelIDList", "",
                "@TrainingType", DBNull.Value,
                "@BranchID", DBNull.Value,
                "@SpecialBranchID", DBNull.Value,
                "@ClassID", NormalizeFilter(classId),
                "@YearID", yearId,
                "@Semester", semester,
                "@StartDate", DBNull.Value,
                "@EndDate", DBNull.Value,
                "@ExamDateIDList", "");
        }

        private Dictionary<string, object> BuildAggregatedData(DataTable dtbRaw)
        {
            Dictionary<string, object> dicResult = new Dictionary<string, object>();

            int intTotal = dtbRaw.Rows.Count;
            int intEligible = 0;
            int intNotEligible = 0;

            Dictionary<string, ClassAgg> dicClass = new Dictionary<string, ClassAgg>();
            Dictionary<string, CourseAgg> dicCourse = new Dictionary<string, CourseAgg>();
            Dictionary<string, ScienceAgg> dicScience = new Dictionary<string, ScienceAgg>();
            Dictionary<string, int> dicGraduationLevel = new Dictionary<string, int>();

            int intRow;
            for (intRow = 0; intRow < dtbRaw.Rows.Count; intRow++)
            {
                DataRow drw = dtbRaw.Rows[intRow];
                bool bolEligible = IsEligibleGraduation(drw);

                if (bolEligible)
                    intEligible++;
                else
                    intNotEligible++;

                string strClassKey = GetRowString(drw, "ClassID1");
                if (strClassKey == "")
                    strClassKey = GetRowString(drw, "ClassName");
                string strClassName = GetRowString(drw, "ClassName");
                if (strClassName == "")
                    strClassName = strClassKey;

                ClassAgg objClassAgg;
                if (!dicClass.TryGetValue(strClassKey, out objClassAgg))
                {
                    objClassAgg = new ClassAgg();
                    objClassAgg.ClassID = strClassKey;
                    objClassAgg.ClassName = strClassName;
                    dicClass[strClassKey] = objClassAgg;
                }
                objClassAgg.TotalCount++;
                if (bolEligible)
                    objClassAgg.EligibleCount++;
                else
                    objClassAgg.NotEligibleCount++;

                string strCourseKey = GetRowString(drw, "CourseID");
                string strCourseName = GetRowString(drw, "CourseName");
                if (strCourseName == "")
                    strCourseName = strCourseKey;
                CourseAgg objCourseAgg;
                if (!dicCourse.TryGetValue(strCourseKey, out objCourseAgg))
                {
                    objCourseAgg = new CourseAgg();
                    objCourseAgg.CourseID = strCourseKey;
                    objCourseAgg.CourseName = strCourseName;
                    dicCourse[strCourseKey] = objCourseAgg;
                }
                objCourseAgg.TotalCount++;
                if (bolEligible)
                    objCourseAgg.EligibleCount++;

                string strScienceKey = GetRowString(drw, "ScienceID");
                string strScienceLabel = GetRowString(drw, "BranchName");
                if (strScienceLabel == "")
                    strScienceLabel = GetRowString(drw, "SpecialBranchName");
                if (strScienceLabel == "")
                    strScienceLabel = strScienceKey;
                ScienceAgg objScienceAgg;
                if (!dicScience.TryGetValue(strScienceKey, out objScienceAgg))
                {
                    objScienceAgg = new ScienceAgg();
                    objScienceAgg.ScienceID = strScienceKey;
                    objScienceAgg.ScienceName = strScienceLabel;
                    dicScience[strScienceKey] = objScienceAgg;
                }
                objScienceAgg.TotalCount++;
                if (bolEligible)
                    objScienceAgg.EligibleCount++;

                if (bolEligible)
                {
                    string strLevel = GetRowString(drw, "GraduationLevel");
                    if (strLevel == "")
                        strLevel = "Chưa xếp loại";
                    int intLevelCount;
                    if (!dicGraduationLevel.TryGetValue(strLevel, out intLevelCount))
                        intLevelCount = 0;
                    dicGraduationLevel[strLevel] = intLevelCount + 1;
                }
            }

            decimal decRate = 0;
            if (intTotal > 0)
                decRate = Math.Round((decimal)intEligible * 100m / intTotal, 1);

            List<Dictionary<string, object>> lstSummary = new List<Dictionary<string, object>>();
            Dictionary<string, object> dicSummaryRow = new Dictionary<string, object>();
            dicSummaryRow["TotalReviewStudent"] = intTotal;
            dicSummaryRow["EligibleStudent"] = intEligible;
            dicSummaryRow["NotEligibleStudent"] = intNotEligible;
            dicSummaryRow["GraduationRate"] = decRate;
            dicSummaryRow["TotalClass"] = dicClass.Count;
            lstSummary.Add(dicSummaryRow);

            List<Dictionary<string, object>> lstEligibleStatus = new List<Dictionary<string, object>>();
            lstEligibleStatus.Add(BuildStatusRow("Đủ điều kiện TN", intEligible));
            lstEligibleStatus.Add(BuildStatusRow("Chưa đủ điều kiện TN", intNotEligible));

            dicResult["summary"] = lstSummary;
            dicResult["eligibleStatus"] = lstEligibleStatus;
            dicResult["byClass"] = BuildClassList(dicClass);
            dicResult["byCourse"] = BuildCourseList(dicCourse);
            dicResult["byScience"] = BuildScienceList(dicScience);
            dicResult["graduationLevel"] = BuildGraduationLevelList(dicGraduationLevel);

            return dicResult;
        }

        private Dictionary<string, object> BuildStatusRow(string name, int count)
        {
            Dictionary<string, object> dicRow = new Dictionary<string, object>();
            dicRow["StatusName"] = name;
            dicRow["StudentCount"] = count;
            return dicRow;
        }

        private List<Dictionary<string, object>> BuildClassList(Dictionary<string, ClassAgg> dicClass)
        {
            List<ClassAgg> lstClass = new List<ClassAgg>(dicClass.Values);
            lstClass.Sort(delegate(ClassAgg a, ClassAgg b)
            {
                return b.TotalCount.CompareTo(a.TotalCount);
            });

            List<Dictionary<string, object>> lstResult = new List<Dictionary<string, object>>();
            int intIndex;
            for (intIndex = 0; intIndex < lstClass.Count; intIndex++)
            {
                ClassAgg objAgg = lstClass[intIndex];
                decimal decRate = 0;
                if (objAgg.TotalCount > 0)
                    decRate = Math.Round((decimal)objAgg.EligibleCount * 100m / objAgg.TotalCount, 1);

                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                dicRow["ClassID"] = objAgg.ClassID;
                dicRow["ClassName"] = objAgg.ClassName;
                dicRow["TotalCount"] = objAgg.TotalCount;
                dicRow["EligibleCount"] = objAgg.EligibleCount;
                dicRow["NotEligibleCount"] = objAgg.NotEligibleCount;
                dicRow["GraduationRate"] = decRate;
                lstResult.Add(dicRow);
            }
            return lstResult;
        }

        private List<Dictionary<string, object>> BuildCourseList(Dictionary<string, CourseAgg> dicCourse)
        {
            List<CourseAgg> lstCourse = new List<CourseAgg>(dicCourse.Values);
            lstCourse.Sort(delegate(CourseAgg a, CourseAgg b)
            {
                return a.CourseName.CompareTo(b.CourseName);
            });

            List<Dictionary<string, object>> lstResult = new List<Dictionary<string, object>>();
            int intIndex;
            for (intIndex = 0; intIndex < lstCourse.Count; intIndex++)
            {
                CourseAgg objAgg = lstCourse[intIndex];
                decimal decRate = 0;
                if (objAgg.TotalCount > 0)
                    decRate = Math.Round((decimal)objAgg.EligibleCount * 100m / objAgg.TotalCount, 1);

                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                dicRow["CourseID"] = objAgg.CourseID;
                dicRow["CourseName"] = objAgg.CourseName;
                dicRow["TotalCount"] = objAgg.TotalCount;
                dicRow["EligibleCount"] = objAgg.EligibleCount;
                dicRow["NotEligibleCount"] = objAgg.TotalCount - objAgg.EligibleCount;
                dicRow["GraduationRate"] = decRate;
                lstResult.Add(dicRow);
            }
            return lstResult;
        }

        private List<Dictionary<string, object>> BuildScienceList(Dictionary<string, ScienceAgg> dicScience)
        {
            List<ScienceAgg> lstScience = new List<ScienceAgg>(dicScience.Values);
            lstScience.Sort(delegate(ScienceAgg a, ScienceAgg b)
            {
                return b.TotalCount.CompareTo(a.TotalCount);
            });

            List<Dictionary<string, object>> lstResult = new List<Dictionary<string, object>>();
            int intIndex;
            for (intIndex = 0; intIndex < lstScience.Count; intIndex++)
            {
                ScienceAgg objAgg = lstScience[intIndex];
                decimal decRate = 0;
                if (objAgg.TotalCount > 0)
                    decRate = Math.Round((decimal)objAgg.EligibleCount * 100m / objAgg.TotalCount, 1);

                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                dicRow["ScienceID"] = objAgg.ScienceID;
                dicRow["ScienceName"] = objAgg.ScienceName;
                dicRow["TotalCount"] = objAgg.TotalCount;
                dicRow["EligibleCount"] = objAgg.EligibleCount;
                dicRow["NotEligibleCount"] = objAgg.TotalCount - objAgg.EligibleCount;
                dicRow["GraduationRate"] = decRate;
                lstResult.Add(dicRow);
            }
            return lstResult;
        }

        private List<Dictionary<string, object>> BuildGraduationLevelList(Dictionary<string, int> dicLevel)
        {
            List<KeyValuePair<string, int>> lstLevel = new List<KeyValuePair<string, int>>(dicLevel);
            lstLevel.Sort(delegate(KeyValuePair<string, int> a, KeyValuePair<string, int> b)
            {
                return b.Value.CompareTo(a.Value);
            });

            List<Dictionary<string, object>> lstResult = new List<Dictionary<string, object>>();
            int intIndex;
            for (intIndex = 0; intIndex < lstLevel.Count; intIndex++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                dicRow["GraduationLevel"] = lstLevel[intIndex].Key;
                dicRow["StudentCount"] = lstLevel[intIndex].Value;
                lstResult.Add(dicRow);
            }
            return lstResult;
        }

        private bool IsEligibleGraduation(DataRow drw)
        {
            object objCerIssued = drw["CerIssued"];
            if (objCerIssued != null && objCerIssued != DBNull.Value)
            {
                if (objCerIssued is bool)
                    return (bool)objCerIssued;
                try
                {
                    int intCer = Convert.ToInt32(objCerIssued);
                    if (intCer == 1)
                        return true;
                }
                catch (Exception)
                {
                }
            }

            string strLevel = GetRowString(drw, "GraduationLevel");
            if (strLevel != "")
                return true;

            string strDecision = GetRowString(drw, "DecisionNo");
            if (strDecision != "")
                return true;

            return false;
        }

        private string GetRowString(DataRow drw, string columnName)
        {
            if (drw.Table.Columns.Contains(columnName) == false)
                return "";
            if (drw[columnName] == null || drw[columnName] == DBNull.Value)
                return "";
            return drw[columnName].ToString().Trim();
        }

        private string BuildIdListParam(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return "";
            return ";" + value.Trim() + ";";
        }

        private object NormalizeFilter(string value)
        {
            if (value == null || value.Trim() == "" || value == "0" || value.ToLower() == "all")
                return DBNull.Value;
            return value.Trim();
        }

        private List<Dictionary<string, object>> DataTableToList(DataTable dtb)
        {
            List<Dictionary<string, object>> lstRows = new List<Dictionary<string, object>>();
            if (dtb == null)
                return lstRows;

            int intCol;
            int intRow;
            for (intRow = 0; intRow < dtb.Rows.Count; intRow++)
            {
                Dictionary<string, object> dicRow = new Dictionary<string, object>();
                for (intCol = 0; intCol < dtb.Columns.Count; intCol++)
                {
                    object objValue = dtb.Rows[intRow][intCol];
                    if (objValue == DBNull.Value)
                        dicRow[dtb.Columns[intCol].ColumnName] = null;
                    else if (objValue is DateTime)
                        dicRow[dtb.Columns[intCol].ColumnName] = ((DateTime)objValue).ToString("yyyy-MM-dd");
                    else
                        dicRow[dtb.Columns[intCol].ColumnName] = objValue;
                }
                lstRows.Add(dicRow);
            }
            return lstRows;
        }

        private string GetRequestValue(HttpContext context, string key)
        {
            if (context.Request[key] != null && context.Request[key] != "")
                return context.Request[key];

            string strBody = ReadRequestBody(context);
            if (strBody == null || strBody == "")
                return null;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            Dictionary<string, object> dicBody = objSerializer.Deserialize<Dictionary<string, object>>(strBody);
            if (dicBody == null || !dicBody.ContainsKey(key) || dicBody[key] == null)
                return null;

            return Convert.ToString(dicBody[key]);
        }

        private string ReadRequestBody(HttpContext context)
        {
            if (context.Request.InputStream == null)
                return null;

            context.Request.InputStream.Position = 0;
            StreamReader objReader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            return objReader.ReadToEnd();
        }

        private void WriteJson(HttpContext context, bool success, string message, object data)
        {
            Dictionary<string, object> dicResponse = new Dictionary<string, object>();
            dicResponse["success"] = success;
            dicResponse["message"] = message;
            dicResponse["data"] = data;

            JavaScriptSerializer objSerializer = new JavaScriptSerializer();
            objSerializer.MaxJsonLength = int.MaxValue;
            context.Response.Write(objSerializer.Serialize(dicResponse));
        }

        public bool IsReusable
        {
            get { return false; }
        }

        private class ClassAgg
        {
            public string ClassID;
            public string ClassName;
            public int TotalCount;
            public int EligibleCount;
            public int NotEligibleCount;
        }

        private class CourseAgg
        {
            public string CourseID;
            public string CourseName;
            public int TotalCount;
            public int EligibleCount;
        }

        private class ScienceAgg
        {
            public string ScienceID;
            public string ScienceName;
            public int TotalCount;
            public int EligibleCount;
        }
    }
