        var overlay = getEl("sgdDashFullscreenOverlay");
        var titleEl = getEl("sgdDashFullscreenTitle");
        var chartWrap = getEl("sgdDashFullscreenChartWrap");
        var state = fullscreenStates[stateKey];
        var options;
        if (!overlay || !state || !state.optionsBuilder) {
            return;
        }
        if (overlay.parentNode !== document.body) {
            document.body.appendChild(overlay);
        }
        if (titleEl) {
            titleEl.textContent = state.title || "Biểu đồ chi tiết";
        }
        options = state.optionsBuilder();
        if (chartWrap && options && options.chart) {
            chartWrap.style.height = options.chart.height + "px";
        }
        renderChart("#sgdDashChartPrimaryFullscreen", options, null);
        overlay.className = "sgd-dash-fullscreen sgd-dash-fullscreen-horizontal";
        document.body.style.overflow = "hidden";
        if (chartInstances["#sgdDashChartPrimaryFullscreen"]) {
            chartInstances["#sgdDashChartPrimaryFullscreen"].windowResizeHandler();
        }
    }

    function closeFullscreen() {
        var overlay = getEl("sgdDashFullscreenOverlay");
        var chartWrap = getEl("sgdDashFullscreenChartWrap");
        if (!overlay) {
            return;
        }
        overlay.className = "sgd-dash-fullscreen d-none";
        document.body.style.overflow = "";
        destroyChart("#sgdDashChartPrimaryFullscreen");
        if (chartWrap) {
            chartWrap.style.height = "";
        }
    }

    function bindEvents() {
        if (eventsBound) {
            return;
        }
        eventsBound = true;

        var btnLoad = getEl("sgdDashBtnLoad");
        var btnRefresh = getEl("sgdDashBtnRefresh");
        var btnClose = getEl("sgdDashBtnCloseFullscreen");
        var scienceEl = document.getElementById(filterConfig.scienceId);
        var courseEl = document.getElementById(filterConfig.courseId);

        if (btnLoad) {
            btnLoad.addEventListener("click", fetchDashboard);
        }
        if (btnRefresh) {
            btnRefresh.addEventListener("click", fetchDashboard);
        }
        if (btnClose) {
            btnClose.addEventListener("click", closeFullscreen);
        }
        if (scienceEl) {
            scienceEl.addEventListener("change", refreshClassDropdown);
        }
        if (courseEl) {
            courseEl.addEventListener("change", refreshClassDropdown);
        }

        var fsButtons = [
            { id: "sgdDashBtnFullscreenTopGraduated", key: "topGraduated" },
            { id: "sgdDashBtnFullscreenTopNotGraduated", key: "topNotGraduated" },
            { id: "sgdDashBtnFullscreenByCourse", key: "byCourse" },
            { id: "sgdDashBtnFullscreenByScience", key: "byScience" },
            { id: "sgdDashBtnFullscreenClassStack", key: "classStack" }
        ];
        var i;
        for (i = 0; i < fsButtons.length; i++) {
            (function (item) {
                var btn = getEl(item.id);
                if (btn) {
                    btn.addEventListener("click", function () {
                        openFullscreen(item.key);
                    });
                    btn.disabled = true;
                }
            })(fsButtons[i]);
        }

        document.addEventListener("keydown", function (e) {
            if (e.key === "Escape") {
                closeFullscreen();
            }
        });
    }

    function initStudentGraduationDashboard() {
        if (!getEl("sgdDashContent")) {
            return;
        }
        bindEvents();
        fetchDashboard();
    }

    function bootStudentGraduationDashboard() {
        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initStudentGraduationDashboard);
        } else {
            initStudentGraduationDashboard();
        }
    }

    bootStudentGraduationDashboard();
})();
